INSERT INTO CRM_APPROVAL_AUTH(
	SEQ, CUST_CODE, GUBUN, P_CODE, CODE, REG_ID, REG_DATE
) VALUES(
	MAX_APPROVAL_AUTH.NEXTVAL, #{cust_code}, #{gubun}, #{p_code}, #{code}, #{reg_id}, SYSDATE  		
)

mapper.select:
SELECT 
	COUNT(*)
FROM 
CRM_APPROVAL_AUTH
WHERE 1=1 
AND CUST_CODE = #{cust_code}
AND P_CODE = #{p_code}
AND CODE = #{code}
AND GUBUN = #{gubun}

SELECT count(A.SEQ) AS CNT
FROM CRM_APPROVAL_AUTH A, CRM_CUST_MGT M WHERE 1=1 AND A.CUST_CODE = M.ERP_CODE
AND UPPER(M.CUST_KOR_NAME) LIKE '%'|| UPPER(#{search_text}) ||'%'
AND A.P_CODE =#{search_type1}
AND A.CODE = #{search_type2}

SELECT IN_TB.* FROM( SELECT A.SEQ ,A.CUST_CODE ,A.GUBUN ,A.P_CODE ,A.CODE ,(SELECT Z.P_CODE_NAME FROM CRM_CODE_MASTER Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = A.P_CODE) P_CODE_NM ,(SELECT Z.CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD03' AND Z.CODE = A.CODE) CODE_NM ,TO_CHAR(A.REG_DATE,'YYYY-MM-DD') REG_DATE ,A.REG_ID ,M.AS_APPROVAL_YN ,M.CUST_KOR_NAME ,ROW_NUMBER() OVER (ORDER BY A.SEQ ) AS RNUM FROM CRM_APPROVAL_AUTH A, CRM_CUST_MGT M WHERE 1=1 AND A.CUST_CODE = M.ERP_CODE
AND UPPER(M.CUST_KOR_NAME) LIKE '%'|| UPPER(#{search_text}) ||'%'
AND A.P_CODE =#{search_type1}
AND A.CODE = #{search_type2}
)IN_TB WHERE RNUM BETWEEN #{startRow, jdbcType=INTEGER} AND #{endRow, jdbcType=INTEGER} ORDER BY RNUM DESC

mapper.delete:
DELETE FROM CRM_APPROVAL_AUTH 
WHERE 1=1 
AND SEQ = #{seq}

mapper.select:
SELECT IN_TB.* ,(SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'PROJECT' AND z.p_code = 'PR02' AND z.code = IN_TB.system_code) AS system_name ,(SELECT Z.code_name FROM crm_code_detail z WHERE z.code_group = 'AS' AND z.p_code = 'CD13' AND z.code = IN_TB.category_id) category_name FROM ( SELECT A.SYSTEM as system_code ,A.CATEGORIES as category_id ,A.PROGRAM_CODE as program_id ,A.PROGRAM_NM as program_name ,A.USE_YN as use_yn ,ROW_NUMBER() OVER (ORDER BY A.PROGRAM_CODE ) AS seq FROM CRM_AS_PROGRAM_MGT A WHERE 1=1
AND A.PROGRAM_CODE LIKE '%' || #{search_type1} || '%'
AND A.PROGRAM_NM LIKE '%' || #{search_type2} || '%'
AND A.SYSTEM = #{search_type3}
AND A.CATEGORIES IN (SELECT CODE FROM CRM_CODE_DETAIL WHERE CODE_GROUP = 'AS' AND P_CODE = 'CD13' AND (UPPER(CODE_NAME) LIKE '%'|| UPPER(#{search_type4}) ||'%' OR CODE LIKE '%' || #{search_type4}||'%') )
)IN_TB WHERE seq BETWEEN #{startRow, jdbcType=INTEGER} AND #{endRow, jdbcType=INTEGER}

